	fn bare_wide_property(value u32, data string) bool {
		mut low := 0
		mut high := data.len / 8
		for low < high {
			middle := low + (high - low) / 2
			first := bare_character_word(data, middle * 8)
			last := bare_character_word(data, middle * 8 + 4)
			if value < first {
				high = middle
			} else if value > last {
				low = middle + 1
			} else {
				return true
			}
		}
		return false
	}

	fn bare_wide_letter(value u32) bool { return bare_wide_property(value, bare_alphabetic_ranges) }
	fn bare_wide_lower(value u32) bool { return bare_wide_property(value, bare_lowercase_ranges) }
	fn bare_wide_upper(value u32) bool { return bare_wide_property(value, bare_uppercase_ranges) }
